```python
# Initialize the bank's balance dictionary
bank_balance = {}

def main():
    """Simulate a simple bank with deposit, withdraw, and check balance functions."""

    while True:
        user_input = input("Enter a command (deposit, withdraw, check, or quit): ").lower()

        if user_input == "quit":
            print("Goodbye!")
            break
        elif user_input == "deposit":
            amount = float(input("Enter the amount to deposit: $"))
            user_name = input("Enter your name: ")

            if user_name not in bank_balance:
                bank_balance[user_name] = 0

            bank_balance[user_name] += amount
            print(f"Balance for {user_name}: ${bank_balance[user_name]}")
        elif user_input == "withdraw":
            amount = float(input("Enter the amount to withdraw: $"))
            user_name = input("Enter your name: ")

            if user_name in bank_balance:
                if amount <= bank_balance[user_name]:
                    bank_balance[user_name] -= amount
                    print(f"Balance for {user_name}: ${bank_balance[user_name]}")
                else:
                    print(f"Insufficient funds. Current balance: ${bank_balance[user_name]}")
            else:
                print(f"Account not found. Current balance: ${bank_balance[user_name]}")
        elif user_input == "check":
            user_name = input("Enter your name: ")

            if user_name in bank_balance:
                print(f"Balance for {user_name}: ${bank_balance[user_name]}")
            else:
                print(f"Account not found. Current balance: ${bank_balance[user_name]}")
        else:
            print("Invalid command. Please try again.")


if __name__ == "__main__":
    main()
```

This program allows users to deposit, withdraw, and check their balance. The `main()` function handles user input and updates the bank's balance dictionary accordingly.
